const h = $json;
const errors = [];
if (h.ok !== true) errors.push('ok');
if (String(h.service || '') !== 'sm3-media-worker') errors.push('service');
if (String(h.version || '') !== '2.3.0') errors.push(`version=${h.version}`);
if (String(h.production_edit_contract || '') !== 'SM3_PRODUCTION_EDIT_V1') errors.push('production_edit_contract');
if (h.variant_planner_idempotent !== true) errors.push('variant_planner_idempotent');
if (String(h.variant_preview_contract || '') !== 'SM3_VARIANT_PREVIEW_V1') errors.push('variant_preview_contract');
if (h.edit_session_start !== true) errors.push('edit_session_start');
if (h.edit_session_start_idempotent !== true) errors.push('edit_session_start_idempotent');
if (String(h.edit_session_contract || '') !== 'SM3_EDIT_SESSION_V1') errors.push('edit_session_contract');
if (errors.length) throw new Error(`WORKER_2_3_0_CONTRACT_MISMATCH:${errors.join(',')}`);
return {json:{status:'WORKER_2_3_0_CONTRACT_VERIFIED', checked_at:new Date().toISOString()}};

const rows = $input.all().map(i => i.json);
const upper = v => String(v || '').trim().toUpperCase();
const text = v => String(v || '').trim();
const starts = [];
const blocked = [];
let currentCount = 0;
const idCounts = new Map();
for (const row of rows) {
  const id = text(row.ID_CONTEÚDO);
  if (id) idCounts.set(id, (idCounts.get(id) || 0) + 1);
}

for (const r of rows) {
  const projectId = text(r.ID_PROJETO);
  const contentId = text(r.ID_CONTEÚDO);
  const setId = text(r.VARIANT_SET_ID);
  const review = upper(r.VARIANT_REVIEW_STATUS);
  const selected = upper(r.SELECTED_VARIANT_ID);
  const revisionMode = upper(r.REVISION_MODE);
  const render = upper(r.RENDER_STATUS);
  const pipeline = upper(r.PIPELINE_STATE);
  const contract = text(r.PRODUCTION_CONTRACT_VERSION);
  const sessionId = text(r.EDIT_SESSION_ID);
  const sessionStatus = upper(r.EDIT_SESSION_STATUS);
  const stateVersion = text(r.STATE_VERSION);

  const isCommitted = review === 'OPEN_EDITOR' && /^V\d{2}$/.test(selected) &&
    /^ES_[A-Za-z0-9_-]+$/.test(sessionId) && ['OPEN','SAVED','COMPLETED'].includes(sessionStatus) &&
    revisionMode === 'VARIANT_SELECTION' && pipeline === 'EDIT_SESSION_READY' &&
    stateVersion === 'SM3_STATE_V5' && contract === 'SM3_PRODUCTION_EDIT_V1';
  if (isCommitted) { currentCount += 1; continue; }

  const reviewStage = render === 'VARIANT_PREVIEWS_READY' &&
    ['VARIANT_REVIEW_READY','EDIT_SESSION_READY'].includes(pipeline);
  const hasSelectionSignal = review === 'SELECTED' ||
    (reviewStage && Boolean(selected)) ||
    (reviewStage && revisionMode === 'VARIANT_SELECTION');
  if (!hasSelectionSignal) continue;

  const errors = [];
  if (!projectId) errors.push('ID_PROJETO_MISSING');
  if (!contentId) errors.push('ID_CONTEUDO_MISSING');
  if (contentId && idCounts.get(contentId) !== 1) errors.push('ID_CONTEUDO_NOT_UNIQUE');
  if (!/^VS_[A-Za-z0-9_-]+$/.test(setId)) errors.push('VARIANT_SET_ID_INVALID');
  if (review !== 'SELECTED') errors.push(`VARIANT_REVIEW_STATUS=${review || 'EMPTY'}`);
  if (!/^V\d{2}$/.test(selected)) errors.push(`SELECTED_VARIANT_ID=${selected || 'EMPTY'}`);
  const selectedNumber = /^V\d{2}$/.test(selected) ? Number(selected.slice(1)) : 0;
  const variantCount = Number(r.VARIANT_COUNT || 0);
  if (!Number.isInteger(variantCount) || variantCount < 1) errors.push('VARIANT_COUNT_INVALID');
  if (selectedNumber < 1 || selectedNumber > variantCount) errors.push('SELECTED_VARIANT_OUT_OF_RANGE');
  if (render !== 'VARIANT_PREVIEWS_READY') errors.push(`RENDER_STATUS=${render || 'EMPTY'}`);
  if (pipeline !== 'VARIANT_REVIEW_READY') errors.push(`PIPELINE_STATE=${pipeline || 'EMPTY'}`);
  if (contract !== 'SM3_PRODUCTION_EDIT_V1') errors.push(`PRODUCTION_CONTRACT_VERSION=${contract || 'EMPTY'}`);
  if (!['','UNDECIDED','VARIANT_SELECTION'].includes(revisionMode)) errors.push(`REVISION_MODE=${revisionMode}`);
  if (sessionId) errors.push('EDIT_SESSION_ID_ALREADY_SET');
  if (!['','NOT_STARTED'].includes(sessionStatus)) errors.push(`EDIT_SESSION_STATUS=${sessionStatus}`);

  if (errors.length) {
    blocked.push({project_id:projectId, content_id:contentId, errors});
    continue;
  }

  starts.push({
    route_key:'START',
    project_id:projectId,
    content_id:contentId,
    variant_set_id:setId,
    variant_id:selected,
    selection_source:'HUMAN_GOOGLE_SHEETS',
    force_new:false
  });
}

if (blocked.length) {
  return [{json:{route_key:'BLOCKED', status:'VARIANT_SELECTION_BLOCKED', blocked}}];
}
if (starts.length) return starts.map(x => ({json:x}));
return [{json:{route_key:'NO_WORK', status:'NO_EXPLICIT_VARIANT_SELECTION', existing_sessions:currentCount}}];

const x = $json;
const errors = [];
if (x.ok !== true) errors.push('ok');
if (String(x.version || '') !== '2.3.0') errors.push(`version=${x.version}`);
if (String(x.production_contract_version || '') !== 'SM3_PRODUCTION_EDIT_V1') errors.push('production_contract_version');
if (String(x.edit_session_contract_version || '') !== 'SM3_EDIT_SESSION_V1') errors.push('edit_session_contract_version');
if (String(x.edit_contract_version || '') !== 'SM3_EDIT_RECIPE_V1') errors.push('edit_contract_version');
if (!/^ES_[A-Za-z0-9_-]+$/.test(String(x.edit_session_id || ''))) errors.push('edit_session_id');
if (!/^VS_[A-Za-z0-9_-]+$/.test(String(x.variant_set_id || ''))) errors.push('variant_set_id');
if (!/^V\d{2}$/.test(String(x.base_variant_id || ''))) errors.push('base_variant_id');
if (!['OPEN','SAVED','COMPLETED'].includes(String(x.status || ''))) errors.push(`status=${x.status}`);
if (Number(x.current_revision || 0) < 1) errors.push('current_revision');
if (!x.selection_evidence || String(x.selection_evidence.preview_contract_version || '') !== 'SM3_VARIANT_PREVIEW_V1') errors.push('selection_evidence_contract');
if (!/^[a-f0-9]{64}$/.test(String(x.selection_evidence?.preview_sha256 || ''))) errors.push('selection_evidence_hash');
if (!String(x.state_path || '').endsWith('/current.json')) errors.push('state_path');
if (errors.length) throw new Error(`EDIT_SESSION_START_CONTRACT_MISMATCH:${errors.join(',')}`);
return {json:x};

const persisted = $json;
const started = $('WORKER — START EDIT SESSION').all().map(i => i.json).find(x => String(x.edit_session_id || '') === String(persisted.edit_session_id || ''));
if (!started) throw new Error(`EDIT_SESSION_START_RESPONSE_NOT_FOUND:${persisted.edit_session_id || 'EMPTY'}`);
const fields = ['project_id','content_id','variant_set_id','base_variant_id','edit_session_id','start_fingerprint','edit_session_contract_version','edit_contract_version'];
for (const field of fields) {
  if (String(persisted[field] || '') !== String(started[field] || '')) throw new Error(`EDIT_SESSION_PERSIST_MISMATCH:${field}`);
}
if (!['OPEN','SAVED','COMPLETED'].includes(String(persisted.status || ''))) throw new Error(`EDIT_SESSION_PERSIST_STATUS_INVALID:${persisted.status}`);
if (Number(persisted.current_revision || 0) < 1) throw new Error('EDIT_SESSION_PERSIST_REVISION_INVALID');
if (String(persisted.selection_evidence?.preview_sha256 || '') !== String(started.selection_evidence?.preview_sha256 || '')) throw new Error('EDIT_SESSION_PERSIST_PREVIEW_HASH_MISMATCH');
return {json:{
  ID_CONTEÚDO:String(persisted.content_id),
  VARIANT_REVIEW_STATUS:'OPEN_EDITOR',
  SELECTED_VARIANT_ID:String(persisted.base_variant_id),
  REVISION_MODE:'VARIANT_SELECTION',
  EDIT_SESSION_ID:String(persisted.edit_session_id),
  EDIT_SESSION_STATUS:String(persisted.status),
  EDIT_RECIPE_VERSION:'SM3_EDIT_RECIPE_V1',
  PIPELINE_STATE:'EDIT_SESSION_READY',
  STATE_UPDATED_AT:new Date().toISOString(),
  STATE_VERSION:'SM3_STATE_V5',
  production_contract_version:String(persisted.production_contract_version),
  edit_session_contract_version:String(persisted.edit_session_contract_version),
  current_revision:Number(persisted.current_revision),
  preview_sha256:String(persisted.selection_evidence.preview_sha256),
  state_path:String(persisted.state_path),
  reused_existing:Boolean(started.reused_existing)
}};

const rows = $input.all().map(i => i.json);
const expected = $('ASSERT — SESSION PERSISTED').all().map(i => i.json);
const byId = new Map(rows.map(r => [String(r.ID_CONTEÚDO || ''), r]));
const rowCounts = new Map();
for (const row of rows) { const id = String(row.ID_CONTEÚDO || ''); if (id) rowCounts.set(id, (rowCounts.get(id) || 0) + 1); }
const verified = [];
for (const e of expected) {
  const id = String(e.ID_CONTEÚDO || '');
  const r = byId.get(id);
  if (!r) throw new Error(`EDIT_SESSION_COMMIT_ROW_NOT_FOUND:${id}`);
  if (rowCounts.get(id) !== 1) throw new Error(`EDIT_SESSION_COMMIT_ROW_NOT_UNIQUE:${id}`);
  const checks = {
    VARIANT_REVIEW_STATUS:String(r.VARIANT_REVIEW_STATUS || ''),
    SELECTED_VARIANT_ID:String(r.SELECTED_VARIANT_ID || ''),
    REVISION_MODE:String(r.REVISION_MODE || ''),
    EDIT_SESSION_ID:String(r.EDIT_SESSION_ID || ''),
    EDIT_SESSION_STATUS:String(r.EDIT_SESSION_STATUS || ''),
    EDIT_RECIPE_VERSION:String(r.EDIT_RECIPE_VERSION || ''),
    PIPELINE_STATE:String(r.PIPELINE_STATE || ''),
    STATE_VERSION:String(r.STATE_VERSION || ''),
    PRODUCTION_CONTRACT_VERSION:String(r.PRODUCTION_CONTRACT_VERSION || '')
  };
  const wanted = {
    VARIANT_REVIEW_STATUS:'OPEN_EDITOR',
    SELECTED_VARIANT_ID:e.SELECTED_VARIANT_ID,
    REVISION_MODE:'VARIANT_SELECTION',
    EDIT_SESSION_ID:e.EDIT_SESSION_ID,
    EDIT_SESSION_STATUS:e.EDIT_SESSION_STATUS,
    EDIT_RECIPE_VERSION:'SM3_EDIT_RECIPE_V1',
    PIPELINE_STATE:'EDIT_SESSION_READY',
    STATE_VERSION:'SM3_STATE_V5',
    PRODUCTION_CONTRACT_VERSION:'SM3_PRODUCTION_EDIT_V1'
  };
  for (const [field, value] of Object.entries(wanted)) {
    if (checks[field] !== String(value)) throw new Error(`EDIT_SESSION_COMMIT_MISMATCH:${id}:${field}=${checks[field]} expected=${value}`);
  }
  if (!String(r.STATE_UPDATED_AT || '').trim()) throw new Error(`EDIT_SESSION_COMMIT_MISSING_TIMESTAMP:${id}`);
  verified.push({ID_CONTEÚDO:id, SELECTED_VARIANT_ID:checks.SELECTED_VARIANT_ID, EDIT_SESSION_ID:checks.EDIT_SESSION_ID, EDIT_SESSION_STATUS:checks.EDIT_SESSION_STATUS, STATE_VERSION:checks.STATE_VERSION});
}
return [{json:{status:'EDIT_SESSION_COMMIT_VERIFIED', verified_count:verified.length, verified}}];

const verification = $input.first().json;
const sessions = $('ASSERT — SESSION PERSISTED').all().map(i => i.json);
return [{json:{
  status:'EDIT_SESSIONS_READY',
  commit_verified:verification.status === 'EDIT_SESSION_COMMIT_VERIFIED',
  contents_updated:verification.verified_count,
  sessions:verification.verified,
  worker_state_paths:Object.fromEntries(sessions.map(x => [x.ID_CONTEÚDO,x.state_path])),
  preview_hashes:Object.fromEntries(sessions.map(x => [x.ID_CONTEÚDO,x.preview_sha256])),
  reused_existing_count:sessions.filter(x => x.reused_existing === true).length,
  completed_at:new Date().toISOString()
}}];
